import { decodeSnapshot } from '../snapshot.ts';
import { compareTournamentResults, createTournament, roundPlan, stageSize } from './rules.ts';
import { hasUniquePlayerNames, hasValidPlayerNames } from './names.ts';
import { isTimestamp, objectWithKeys } from './validation-helpers.ts';
import type { Round, TournamentMatch, TournamentPlayer, TournamentState, TurnResult } from './types.ts';

const STATE_KEYS = [
  'activePlayer', 'championSeed', 'completedAt', 'createdAt', 'currentGame',
  'currentMatchIndex', 'matches', 'phase', 'playerCount', 'players',
];
const MATCH_KEYS = ['boardCode', 'next', 'players', 'results', 'round', 'winnerSeed'];
const PLAYER_KEYS = ['name', 'seed'];
const RESULT_KEYS = ['elapsedMs', 'moves'];
const NEXT_KEYS = ['matchIndex', 'playerSlot'];
const ROUNDS: readonly string[] = ['Quarterfinal', 'Semifinal', 'Final'];
const PHASES: readonly string[] = ['ready', 'playing', 'betweenTurns', 'betweenMatches', 'complete'];

export type StateValidation = { readonly state: TournamentState } | { readonly message: string };

export function validateTournamentState(value: unknown): StateValidation {
  try {
    return validate(value);
  } catch (error) {
    return { message: error instanceof Error ? error.message : 'Invalid tournament.' };
  }
}

function validate(value: unknown): StateValidation {
  const raw = objectWithKeys(value, STATE_KEYS);
  if (!raw) return { message: 'Invalid tournament.' };
  if (
    (raw.playerCount !== 4 && raw.playerCount !== 8) ||
    !Array.isArray(raw.players) ||
    !Array.isArray(raw.matches) ||
    !Number.isInteger(raw.currentMatchIndex) ||
    !Number.isInteger(raw.activePlayer) ||
    (raw.activePlayer !== 0 && raw.activePlayer !== 1) ||
    typeof raw.phase !== 'string' ||
    !PHASES.includes(raw.phase) ||
    (raw.currentGame !== null && typeof raw.currentGame !== 'string') ||
    (raw.completedAt !== null && !isTimestamp(raw.completedAt)) ||
    !isTimestamp(raw.createdAt)
  )
    return { message: 'Invalid tournament.' };

  const players = parsePlayers(raw.players);
  if (!players) return { message: 'Invalid tournament.' };
  const matches = parseMatches(raw.matches);
  if (!matches) return { message: 'Invalid tournament.' };
  const state = raw as unknown as TournamentState;
  const semanticError = validateBracket(state, players, matches);
  if (semanticError) return { message: semanticError };
  return { state: { ...state, players, matches } };
}

function parsePlayers(value: readonly unknown[]): TournamentPlayer[] | null {
  const players: TournamentPlayer[] = [];
  for (const item of value) {
    const raw = objectWithKeys(item, PLAYER_KEYS);
    if (!raw || typeof raw.name !== 'string' || !Number.isSafeInteger(raw.seed)) return null;
    players.push({ name: raw.name, seed: raw.seed as number });
  }
  return players;
}

function parseMatches(value: readonly unknown[]): TournamentMatch[] | null {
  const matches: TournamentMatch[] = [];
  for (const item of value) {
    const raw = objectWithKeys(item, MATCH_KEYS);
    if (
      !raw || typeof raw.boardCode !== 'string' || typeof raw.round !== 'string' ||
      !ROUNDS.includes(raw.round) || !Array.isArray(raw.players) || raw.players.length !== 2 ||
      !Array.isArray(raw.results) || raw.results.length !== 2
    )
      return null;
    const players = raw.players;
    if (players.some((seed) => seed !== null && !Number.isSafeInteger(seed))) return null;
    const first = parseResult(raw.results[0]);
    const second = parseResult(raw.results[1]);
    if (first === undefined || second === undefined) return null;
    const next = parseNext(raw.next);
    if (next === undefined || (raw.winnerSeed !== null && !Number.isSafeInteger(raw.winnerSeed)))
      return null;
    matches.push({
      boardCode: raw.boardCode,
      next,
      players: players as [number | null, number | null],
      results: [first, second],
      round: raw.round as Round,
      winnerSeed: raw.winnerSeed as number | null,
    });
  }
  return matches;
}

function parseResult(value: unknown): TurnResult | null | undefined {
  if (value === null) return null;
  const raw = objectWithKeys(value, RESULT_KEYS);
  if (!raw || !Number.isSafeInteger(raw.moves) || typeof raw.elapsedMs !== 'number') return undefined;
  return { elapsedMs: raw.elapsedMs, moves: raw.moves as number };
}

function parseNext(value: unknown): TournamentMatch['next'] | undefined {
  if (value === null) return null;
  const raw = objectWithKeys(value, NEXT_KEYS);
  if (
    !raw || !Number.isInteger(raw.matchIndex) || (raw.playerSlot !== 0 && raw.playerSlot !== 1)
  )
    return undefined;
  return { matchIndex: raw.matchIndex as number, playerSlot: raw.playerSlot };
}

function validateBracket(
  state: TournamentState,
  players: readonly TournamentPlayer[],
  matches: readonly TournamentMatch[],
): string | null {
  const names = players.map((player) => player.name);
  if (
    players.length !== state.playerCount ||
    players.some((player, index) => player.seed !== index + 1) ||
    !hasValidPlayerNames(names) ||
    !hasUniquePlayerNames(names)
  )
    return 'Invalid tournament.';
  const base = createTournament(players, matches.map((match) => match.boardCode), state.createdAt);
  if (!base || matches.length !== roundPlan(state.playerCount).length) return 'Invalid tournament.';
  const expectedPlayers = base.matches.map((match) => [...match.players] as [number | null, number | null]);
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const expected = base.matches[index];
    if (!match || !expected || match.round !== expected.round || !sameNext(match.next, expected.next))
      return 'Invalid tournament.';
    if (match.players[0] !== expectedPlayers[index]?.[0] || match.players[1] !== expectedPlayers[index]?.[1])
      return 'Invalid tournament.';
    if (!validResults(match) || !validWinner(match)) return 'Invalid tournament.';
    if (match.winnerSeed !== null && match.next) {
      const target = expectedPlayers[match.next.matchIndex];
      if (!target) return 'Invalid tournament.';
      target[match.next.playerSlot] = match.winnerSeed;
    }
  }
  return validatePhase(state);
}

function validResults(match: TournamentMatch): boolean {
  if (match.results[1] && !match.results[0]) return false;
  for (const result of match.results) {
    if (!result) continue;
    if (
      !Number.isSafeInteger(result.moves) || result.moves < stageSize(match.round) ** 2 / 2 ||
      result.moves > 999_999 || !Number.isFinite(result.elapsedMs) || result.elapsedMs < 0 ||
      result.elapsedMs > 359_999_999
    )
      return false;
  }
  return true;
}

function validWinner(match: TournamentMatch): boolean {
  const [first, second] = match.results;
  if (!first || !second) return match.winnerSeed === null;
  const [firstSeed, secondSeed] = match.players;
  if (firstSeed === null || secondSeed === null) return false;
  const winner = compareTournamentResults(first, firstSeed, second, secondSeed) <= 0 ? firstSeed : secondSeed;
  return match.winnerSeed === winner;
}

function validatePhase(state: TournamentState): string | null {
  const current = state.matches[state.currentMatchIndex];
  if (!current || state.currentMatchIndex < 0) return 'Invalid tournament.';
  for (const match of state.matches.slice(0, state.currentMatchIndex))
    if (match.winnerSeed === null) return 'Invalid tournament.';
  for (const match of state.matches.slice(state.currentMatchIndex + 1))
    if (match.results.some(Boolean) || match.winnerSeed !== null) return 'Invalid tournament.';
  if (state.phase === 'playing') {
    const priorTurnDone = state.activePlayer === 1 && current.results[0] !== null;
    const noCurrentResult = current.results[state.activePlayer] === null;
    const game = typeof state.currentGame === 'string' ? decodeSnapshot(state.currentGame) : null;
    return priorTurnDone && noCurrentResult && game?.boardCode === current.boardCode &&
      game.matched.length < game.deck.length ? null : 'Invalid tournament.';
  }
  if (state.currentGame !== null) return 'Invalid tournament.';
  if (state.phase === 'ready')
    return state.activePlayer === 0 && !current.results.some(Boolean) && noCompletion(state)
      ? null : 'Invalid tournament.';
  if (state.phase === 'betweenTurns')
    return state.activePlayer === 1 && current.results[0] !== null && current.results[1] === null &&
      noCompletion(state) ? null : 'Invalid tournament.';
  if (state.phase === 'betweenMatches')
    return state.activePlayer === 0 && current.winnerSeed !== null &&
      state.currentMatchIndex < state.matches.length - 1 && noCompletion(state)
      ? null : 'Invalid tournament.';
  const final = state.matches[state.matches.length - 1];
  return state.phase === 'complete' && state.currentMatchIndex === state.matches.length - 1 &&
    state.activePlayer === 1 && final?.winnerSeed === state.championSeed &&
    state.championSeed !== null && isTimestamp(state.completedAt)
    ? null : 'Invalid tournament.';
}

function noCompletion(state: TournamentState): boolean {
  return state.championSeed === null && state.completedAt === null;
}

function sameNext(first: TournamentMatch['next'], second: TournamentMatch['next']): boolean {
  return first?.matchIndex === second?.matchIndex && first?.playerSlot === second?.playerSlot;
}

