import { useCallback, useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { isWon } from '../game.ts';
import { encodeTournament, decodeTournament } from './format.ts';
import { hasUniquePlayerNames, hasValidPlayerNames, normalizePlayerName } from './names.ts';
import { TournamentBracket } from './TournamentBracket.tsx';
import { TournamentEntry } from './TournamentEntry.tsx';
import { TournamentHistory } from './TournamentHistory.tsx';
import { tournamentPlayer } from './rules.ts';
import { useTournament } from './use-tournament.ts';
import { useTournamentHistory } from './use-history.ts';
import type { Ref } from 'react';
import type { TournamentPlayer, TournamentState } from './types.ts';
import './tournament.css';

interface TournamentScreenProps {
  readonly headingRef: Ref<HTMLHeadingElement>;
  onBack(): void;
  announce(text: string): void;
}

export function TournamentScreen({ headingRef, onBack, announce }: TournamentScreenProps) {
  const history = useTournamentHistory();
  const onComplete = useCallback((tournament: TournamentState) => history.add(tournament), [history.add]);
  const tournamentController = useTournament({ announce, onComplete });
  const { tournament, controller } = tournamentController;
  const [playerCount, setPlayerCount] = useState(4);
  const [names, setNames] = useState(() => Array.from({ length: 8 }, () => ''));
  const [entryNotice, setEntryNotice] = useState('');
  const [jsonText, setJsonText] = useState('');
  const [jsonNotice, setJsonNotice] = useState('');
  const [focusStart, setFocusStart] = useState(false);
  const startButton = useRef<HTMLButtonElement>(null);
  const board = useRef<BoardFocus>(null);
  const focusBoard = useRef(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const game = controller.session.game;

  useEffect(() => {
    if (headingRef && 'current' in headingRef) headingRef.current?.focus();
    else heading.current?.focus();
  }, [headingRef]);
  useEffect(() => {
    if (!focusStart || !tournament) return;
    startButton.current?.focus();
    setFocusStart(false);
  }, [focusStart, tournament]);
  useEffect(() => {
    if (focusBoard.current && tournament?.phase === 'playing') {
      board.current?.focusRemembered();
      focusBoard.current = false;
    }
  }, [controller.session.generation, tournament?.phase]);

  function changeName(index: number, value: string): void {
    setNames((current) => current.map((name, position) => position === index ? value : name));
  }

  function startTournament(): void {
    const acceptedNames = names.slice(0, playerCount).map(normalizePlayerName);
    if (!hasValidPlayerNames(acceptedNames)) {
      setEntryNotice('Use 2 to 20 characters.');
      announce('Use 2 to 20 characters.');
      return;
    }
    if (!hasUniquePlayerNames(acceptedNames)) {
      setEntryNotice('Each name must be different.');
      announce('Each name must be different.');
      return;
    }
    const players: TournamentPlayer[] = acceptedNames.map((name, index) => ({ name, seed: index + 1 }));
    setEntryNotice('');
    tournamentController.start(players);
    setFocusStart(true);
  }

  function exportTournament(): void {
    const source = tournament ?? history.items[0];
    if (!source) {
      setJsonNotice('There is no tournament to export.');
      return;
    }
    const snapshot = source.phase === 'playing' ? controller.exportSnapshot() : null;
    setJsonText(encodeTournament(source, snapshot));
    setJsonNotice('Tournament exported.');
  }

  function loadTournament(): void {
    const decoded = decodeTournament(jsonText);
    if (!decoded.ok) {
      setJsonNotice(decoded.message);
      announce(decoded.message);
      return;
    }
    if (!tournamentController.load(decoded.tournament)) {
      setJsonNotice('Invalid tournament.');
      announce('Invalid tournament.');
      return;
    }
    setJsonNotice('Tournament loaded.');
  }

  const currentMatch = tournament?.matches[tournament.currentMatchIndex];
  const activeSeed = currentMatch?.players[tournament?.activePlayer ?? 0] ?? null;
  const activeName = tournament && activeSeed !== null
    ? tournamentPlayer(tournament, activeSeed)?.name
    : undefined;
  const champion = tournament
    ? tournamentPlayer(tournament, tournament.championSeed)?.name
    : undefined;
  const showBoard = Boolean(
    tournament && tournament.phase !== 'ready' && isWon(game) === false ||
    tournament && isWon(game) && ['betweenTurns', 'betweenMatches', 'complete'].includes(tournament.phase),
  );

  function beginTurn(): void {
    focusBoard.current = true;
    tournamentController.startTurn();
  }

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={(node) => {
        heading.current = node;
        if (headingRef && 'current' in headingRef) headingRef.current = node;
      }} tabIndex={-1}>
        Tournament
      </h2>
      {!tournament && (
        <>
          <p className="tournament-intro">Enter 4 or 8 players to set up a knockout bracket.</p>
          <TournamentEntry
            playerCount={playerCount}
            names={names}
            notice={entryNotice}
            onPlayerCountChange={(count) => setPlayerCount(count)}
            onNameChange={changeName}
            onStart={startTournament}
          />
          <button type="button" className="control tournament-exit" onClick={onBack}>
            Back to game
          </button>
        </>
      )}
      {tournament && currentMatch && (
        <section className="tournament-current" aria-labelledby="tournament-round-heading">
          <h3 id="tournament-round-heading">Round: {currentMatch.round}</h3>
          <p>Match {tournament.currentMatchIndex + 1} of {tournament.matches.length}</p>
          {tournament.phase !== 'betweenMatches' && tournament.phase !== 'complete' && activeName && (
            <p className="tournament-now-playing">Now playing: {activeName}</p>
          )}
          <p className="tournament-tie-rule">
            Fewer moves wins. Equal move counts go to the faster time, then the higher seed.
          </p>
          {tournament.phase === 'ready' && (
            <button ref={startButton} type="button" className="control" onClick={beginTurn}>
              Start turn
            </button>
          )}
          {tournament.phase === 'betweenTurns' && (
            <button ref={startButton} type="button" className="control" onClick={beginTurn}>
              Next turn
            </button>
          )}
          {tournament.phase === 'betweenMatches' && (
            <button ref={startButton} type="button" className="control" onClick={tournamentController.nextMatch}>
              Next match
            </button>
          )}
          {tournament.phase === 'playing' && <p>Finish the board to continue.</p>}
          {tournament.phase === 'complete' ? (
            <>
              <h3>Champion: {champion}</h3>
              <button type="button" className="control" onClick={onBack}>Back to game</button>
            </>
          ) : (
            <button type="button" className="control" onClick={onBack}>Leave tournament</button>
          )}
          {showBoard && (
            <>
              <GameStatus game={game} best={undefined} celebration={controller.session.celebration} showBest={false} />
              <p id="tournament-board-help" className="help">
                Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
              </p>
              <Board key={controller.session.generation} game={game} activate={controller.activate} ref={board} />
            </>
          )}
          <TournamentBracket tournament={tournament} highlightCurrent />
        </section>
      )}
      <section className="tournament-json" aria-labelledby="tournament-json-heading">
        <h3 id="tournament-json-heading">Tournament JSON</h3>
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control"
          rows={8}
          maxLength={65_536}
          value={jsonText}
          onChange={(event) => setJsonText(event.currentTarget.value)}
        />
        <div className="tournament-actions">
          <button type="button" className="control" onClick={exportTournament}>Export tournament</button>
          <button type="button" className="control" onClick={loadTournament}>Load tournament</button>
        </div>
        <p id="tournament-json-notice" className="tournament-notice" aria-describedby="tournament-json">
          {jsonNotice}
        </p>
      </section>
      <TournamentHistory items={history.items} available={history.available} />
    </section>
  );
}

