import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import { DEFAULT_SIZE } from './storage.ts';
import type { Session } from './session.ts';

interface GameOptions {
  readonly active?: boolean;
  readonly persistPreferences?: boolean;
  readonly recordBest?: boolean;
  readonly initialSize?: number;
}

export function useGame(options: GameOptions = {}) {
  const active = options.active ?? true;
  const persistPreferences = options.persistPreferences ?? true;
  const recordBest = options.recordBest ?? true;
  const [store] = useState(() => (persistPreferences ? browserStore() : null));
  const [session, setSession] = useState(() => {
    const preferences = persistPreferences
      ? readPreferences(store)
      : { size: options.initialSize ?? DEFAULT_SIZE, bestMoves: {} };
    return initialSession(freshBoardCode(options.initialSize ?? preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit, active);
  useSavedPreferences(store, session.preferences, persistPreferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false, persistPreferences));
  }

  function restart(): void {
    clock.reset();
    commit(
      replaceGame(current.current, createGame(current.current.game.boardCode), false, persistPreferences),
    );
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false, persistPreferences));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true, persistPreferences));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index, recordBest));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return { session, newGame, restart, loadBoard, loadSnapshot, exportSnapshot, activate, resume };
}
import { useEffect, useRef } from 'react';
import { isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { CLOCK_INTERVAL_MS, createClock, elapsedStep } from './browser-clock.ts';
import { tickSession } from './session.ts';
import type { RefObject } from 'react';
import type { Session } from './session.ts';

export function useSessionClock(
  session: Session,
  current: RefObject<Session>,
  commit: (next: Session) => void,
  active = true,
) {
  const clock = useRef(createClock(performance.now()));
  const visible = useRef(!document.hidden);
  const won = isWon(session.game);

  function running(): boolean {
    return (
      visible.current &&
      active &&
      !current.current.paused &&
      current.current.game.started &&
      !isWon(current.current.game)
    );
  }

  function synchronize(generation = current.current.generation): void {
    if (generation !== current.current.generation) return;
    const now = performance.now();
    const step = elapsedStep(clock.current, now, running());
    clock.current = step.clock;
    if (step.milliseconds) commit(tickSession(current.current, generation, step.milliseconds));
  }

  useEffect(() => {
    const generation = session.generation;
    clock.current = createClock(performance.now());
    let active = true;
    let timer: number | undefined;
    function schedule(): void {
      window.clearTimeout(timer);
      if (!active || generation !== current.current.generation || !running()) return;
      const selection = current.current.game.selection;
      const delay =
        selection.kind === SelectionKind.mismatch
          ? Math.min(CLOCK_INTERVAL_MS, selection.remainingMs)
          : CLOCK_INTERVAL_MS;
      timer = window.setTimeout(() => {
        if (!active) return;
        synchronize(generation);
        schedule();
      }, delay);
    }
    function visibilityChanged(): void {
      if (!active || generation !== current.current.generation) return;
      synchronize(generation);
      visible.current = !document.hidden;
      schedule();
    }
    schedule();
    document.addEventListener('visibilitychange', visibilityChanged);
    return () => {
      active = false;
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', visibilityChanged);
    };
  }, [active, session.generation, session.game.started, session.paused, won]);

  return {
    synchronize,
    reset: () => {
      clock.current = createClock(performance.now());
    },
  };
}
import { parseBoardCode } from '../deck.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { hasUniquePlayerNames, hasValidPlayerNames } from './names.ts';
import type { Round } from './types.ts';
import type { TournamentMatch, TournamentPlayer, TournamentState, TurnResult } from './types.ts';

export function roundPlan(playerCount: number): readonly Round[] {
  if (playerCount === 4) return ['Semifinal', 'Semifinal', 'Final'];
  if (playerCount === 8)
    return ['Quarterfinal', 'Quarterfinal', 'Quarterfinal', 'Quarterfinal', 'Semifinal', 'Semifinal', 'Final'];
  return [];
}

export function stageSize(round: Round): number {
  if (round === 'Quarterfinal') return 4;
  if (round === 'Semifinal') return 6;
  return 8;
}

export function createTournament(
  players: readonly TournamentPlayer[],
  boardCodes: readonly string[],
  createdAt: string,
): TournamentState | null {
  const plan = roundPlan(players.length);
  if (
    !plan.length ||
    players.some((player, index) => player.seed !== index + 1) ||
    !hasValidPlayerNames(players.map((player) => player.name)) ||
    !hasUniquePlayerNames(players.map((player) => player.name)) ||
    boardCodes.length !== plan.length ||
    new Set(boardCodes).size !== boardCodes.length
  )
    return null;

  if (
    boardCodes.some((code, index) => {
      const parsed = parseBoardCode(code);
      return !parsed || parsed.size !== stageSize(plan[index] ?? 'Final');
    })
  )
    return null;
  const opening = players.length === 4 ? [[1, 4], [2, 3]] : [[1, 8], [4, 5], [3, 6], [2, 7]];
  const openingCount = opening.length;
  const matches: TournamentMatch[] = plan.map((round, index) => {
    const isOpening = index < openingCount;
    const playersForMatch = isOpening
      ? (opening[index] as [number, number])
      : ([null, null] as [null, null]);
    const next = index === plan.length - 1
      ? null
      : index < openingCount
        ? { matchIndex: players.length === 4 ? 2 : 4 + Math.floor(index / 2), playerSlot: index % 2 }
        : { matchIndex: plan.length - 1, playerSlot: index - openingCount };
    return {
      boardCode: boardCodes[index] ?? '',
      next,
      players: playersForMatch,
      results: [null, null],
      round,
      winnerSeed: null,
    };
  });
  return {
    activePlayer: 0,
    championSeed: null,
    completedAt: null,
    createdAt,
    currentGame: null,
    currentMatchIndex: 0,
    matches,
    phase: 'ready',
    playerCount: players.length,
    players,
  };
}

export function beginTournamentTurn(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'ready' && tournament.phase !== 'betweenTurns') return tournament;
  return { ...tournament, currentGame: null, phase: 'playing' };
}

export function advanceTournamentMatch(tournament: TournamentState): TournamentState {
  if (tournament.phase !== 'betweenMatches') return tournament;
  return {
    ...tournament,
    activePlayer: 0,
    currentGame: null,
    currentMatchIndex: tournament.currentMatchIndex + 1,
    phase: 'ready',
  };
}

export function finishTournamentTurn(
  tournament: TournamentState,
  result: TurnResult,
  completedAt: string,
): TournamentState {
  if (tournament.phase !== 'playing' || !isValidTurnResult(result, tournament.matches[tournament.currentMatchIndex]?.round))
    return tournament;
  const index = tournament.currentMatchIndex;
  const match = tournament.matches[index];
  if (!match || match.players[tournament.activePlayer] === null) return tournament;
  const results = [...match.results] as [TurnResult | null, TurnResult | null];
  results[tournament.activePlayer] = result;
  if (tournament.activePlayer === 0) {
    return {
      ...tournament,
      activePlayer: 1,
      currentGame: null,
      matches: replaceMatch(tournament.matches, index, { ...match, results }),
      phase: 'betweenTurns',
    };
  }

  const firstSeed = match.players[0];
  const secondSeed = match.players[1];
  const firstResult = results[0];
  const secondResult = results[1];
  if (firstSeed === null || secondSeed === null || !firstResult || !secondResult) return tournament;
  const winnerSeed = compareTournamentResults(firstResult, firstSeed, secondResult, secondSeed) <= 0
    ? firstSeed
    : secondSeed;
  const finishedMatch = { ...match, results, winnerSeed };
  const matches = [...replaceMatch(tournament.matches, index, finishedMatch)];
  if (match.next) {
    const nextMatch = matches[match.next.matchIndex];
    if (!nextMatch) return tournament;
    const nextPlayers = [...nextMatch.players] as [number | null, number | null];
    nextPlayers[match.next.playerSlot] = winnerSeed;
    matches[match.next.matchIndex] = { ...nextMatch, players: nextPlayers };
    return {
      ...tournament,
      activePlayer: 0,
      currentGame: null,
      matches,
      phase: 'betweenMatches',
    };
  }
  return {
    ...tournament,
    championSeed: winnerSeed,
    completedAt,
    currentGame: null,
    matches,
    phase: 'complete',
  };
}

export function compareTournamentResults(
  first: TurnResult,
  firstSeed: number,
  second: TurnResult,
  secondSeed: number,
): number {
  return first.moves - second.moves || first.elapsedMs - second.elapsedMs || firstSeed - secondSeed;
}

export function tournamentPlayer(tournament: TournamentState, seed: number | null): TournamentPlayer | null {
  return seed === null ? null : tournament.players[seed - 1] ?? null;
}

function isValidTurnResult(result: TurnResult, round: Round | undefined): boolean {
  return (
    round !== undefined &&
    Number.isSafeInteger(result.moves) &&
    result.moves >= stageSize(round) ** 2 / 2 &&
    result.moves <= MOVES_MAX &&
    Number.isFinite(result.elapsedMs) &&
    result.elapsedMs >= 0 &&
    result.elapsedMs <= ELAPSED_MAX_MS
  );
}

function replaceMatch(
  matches: readonly TournamentMatch[],
  index: number,
  match: TournamentMatch,
): TournamentMatch[] {
  return matches.map((entry, position) => (position === index ? match : entry));
}
import { validateTournamentLogic } from './validate-logic.ts';
import { isTimestamp, objectWithKeys } from './validation-helpers.ts';
import type { Round, TournamentMatch, TournamentPlayer, TournamentState, TurnResult } from './types.ts';

const STATE_KEYS = [
  'activePlayer', 'championSeed', 'completedAt', 'createdAt', 'currentGame',
  'currentMatchIndex', 'matches', 'phase', 'playerCount', 'players',
];
const MATCH_KEYS = ['boardCode', 'next', 'players', 'results', 'round', 'winnerSeed'];
const PLAYER_KEYS = ['name', 'seed'];
const RESULT_KEYS = ['elapsedMs', 'moves'];
const NEXT_KEYS = ['matchIndex', 'playerSlot'];
const PHASES: readonly string[] = ['ready', 'playing', 'betweenTurns', 'betweenMatches', 'complete'];

export type StateValidation = { readonly state: TournamentState } | { readonly message: string };

export function validateTournamentState(value: unknown): StateValidation {
  try {
    return validate(value);
  } catch (error) {
    return { message: error instanceof Error ? error.message : 'Invalid tournament.' };
  }
}

function validate(value: unknown): StateValidation {
  const raw = objectWithKeys(value, STATE_KEYS);
  if (!raw) return { message: 'Invalid tournament.' };
  if (
    (raw.playerCount !== 4 && raw.playerCount !== 8) ||
    !Array.isArray(raw.players) ||
    !Array.isArray(raw.matches) ||
    !Number.isInteger(raw.currentMatchIndex) ||
    !Number.isInteger(raw.activePlayer) ||
    (raw.activePlayer !== 0 && raw.activePlayer !== 1) ||
    typeof raw.phase !== 'string' ||
    !PHASES.includes(raw.phase) ||
    (raw.currentGame !== null && typeof raw.currentGame !== 'string') ||
    (raw.completedAt !== null && !isTimestamp(raw.completedAt)) ||
    !isTimestamp(raw.createdAt)
  )
    return { message: 'Invalid tournament.' };

  const players = parsePlayers(raw.players);
  if (!players) return { message: 'Invalid tournament.' };
  const matches = parseMatches(raw.matches);
  if (!matches) return { message: 'Invalid tournament.' };
  const state = raw as unknown as TournamentState;
  const semanticError = validateTournamentLogic(state, players, matches);
  if (semanticError) return { message: semanticError };
  return { state: { ...state, players, matches } };
}

function parsePlayers(value: readonly unknown[]): TournamentPlayer[] | null {
  const players: TournamentPlayer[] = [];
  for (const item of value) {
    const raw = objectWithKeys(item, PLAYER_KEYS);
    if (!raw || typeof raw.name !== 'string' || !Number.isSafeInteger(raw.seed)) return null;
    players.push({ name: raw.name, seed: raw.seed as number });
  }
  return players;
}

function parseMatches(value: readonly unknown[]): TournamentMatch[] | null {
  const matches: TournamentMatch[] = [];
  for (const item of value) {
    const raw = objectWithKeys(item, MATCH_KEYS);
    if (
      !raw || typeof raw.boardCode !== 'string' || typeof raw.round !== 'string' ||
      !['Quarterfinal', 'Semifinal', 'Final'].includes(raw.round) ||
      !Array.isArray(raw.players) || raw.players.length !== 2 ||
      !Array.isArray(raw.results) || raw.results.length !== 2
    )
      return null;
    const players = raw.players;
    if (players.some((seed) => seed !== null && !Number.isSafeInteger(seed))) return null;
    const first = parseResult(raw.results[0]);
    const second = parseResult(raw.results[1]);
    if (first === undefined || second === undefined) return null;
    const next = parseNext(raw.next);
    if (next === undefined || (raw.winnerSeed !== null && !Number.isSafeInteger(raw.winnerSeed)))
      return null;
    matches.push({
      boardCode: raw.boardCode,
      next,
      players: players as [number | null, number | null],
      results: [first, second],
      round: raw.round as Round,
      winnerSeed: raw.winnerSeed as number | null,
    });
  }
  return matches;
}

function parseResult(value: unknown): TurnResult | null | undefined {
  if (value === null) return null;
  const raw = objectWithKeys(value, RESULT_KEYS);
  if (!raw || !Number.isSafeInteger(raw.moves) || typeof raw.elapsedMs !== 'number') return undefined;
  return { elapsedMs: raw.elapsedMs, moves: raw.moves as number };
}

function parseNext(value: unknown): TournamentMatch['next'] | undefined {
  if (value === null) return null;
  const raw = objectWithKeys(value, NEXT_KEYS);
  if (
    !raw || !Number.isInteger(raw.matchIndex) || (raw.playerSlot !== 0 && raw.playerSlot !== 1)
  )
    return undefined;
  return { matchIndex: raw.matchIndex as number, playerSlot: raw.playerSlot };
}

import { decodeSnapshot } from '../snapshot.ts';
import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';
import { hasUniquePlayerNames, hasValidPlayerNames } from './names.ts';
import { compareTournamentResults, createTournament, roundPlan, stageSize } from './rules.ts';
import { isTimestamp } from './validation-helpers.ts';
import type { TournamentMatch, TournamentPlayer, TournamentState } from './types.ts';

export function validateTournamentLogic(
  state: TournamentState,
  players: readonly TournamentPlayer[],
  matches: readonly TournamentMatch[],
): string | null {
  const names = players.map((player) => player.name);
  if (
    players.length !== state.playerCount ||
    players.some((player, index) => player.seed !== index + 1) ||
    !hasValidPlayerNames(names) ||
    !hasUniquePlayerNames(names)
  )
    return 'Invalid tournament.';
  const base = createTournament(players, matches.map((match) => match.boardCode), state.createdAt);
  if (!base || matches.length !== roundPlan(state.playerCount).length) return 'Invalid tournament.';
  const expected = base.matches.map((match) => [...match.players] as [number | null, number | null]);
  for (let index = 0; index < matches.length; index += 1) {
    const match = matches[index];
    const template = base.matches[index];
    if (!match || !template || match.round !== template.round || !sameNext(match.next, template.next))
      return 'Invalid tournament.';
    if (match.players[0] !== expected[index]?.[0] || match.players[1] !== expected[index]?.[1])
      return 'Invalid tournament.';
    if (!validResults(match) || !validWinner(match)) return 'Invalid tournament.';
    if (match.winnerSeed !== null && match.next) {
      const target = expected[match.next.matchIndex];
      if (!target) return 'Invalid tournament.';
      target[match.next.playerSlot] = match.winnerSeed;
    }
  }
  return validatePhase(state);
}

function validResults(match: TournamentMatch): boolean {
  if (match.results[1] && !match.results[0]) return false;
  return match.results.every(
    (result) => !result || (
      Number.isSafeInteger(result.moves) &&
      result.moves >= stageSize(match.round) ** 2 / 2 &&
      result.moves <= MOVES_MAX &&
      Number.isFinite(result.elapsedMs) &&
      result.elapsedMs >= 0 &&
      result.elapsedMs <= ELAPSED_MAX_MS
    ),
  );
}

function validWinner(match: TournamentMatch): boolean {
  const [first, second] = match.results;
  if (!first || !second) return match.winnerSeed === null;
  const [firstSeed, secondSeed] = match.players;
  if (firstSeed === null || secondSeed === null) return false;
  const winner = compareTournamentResults(first, firstSeed, second, secondSeed) <= 0
    ? firstSeed
    : secondSeed;
  return match.winnerSeed === winner;
}

function validatePhase(state: TournamentState): string | null {
  const current = state.matches[state.currentMatchIndex];
  if (!current || state.currentMatchIndex < 0) return 'Invalid tournament.';
  if (state.matches.slice(0, state.currentMatchIndex).some((match) => match.winnerSeed === null))
    return 'Invalid tournament.';
  if (state.matches.slice(state.currentMatchIndex + 1).some((match) =>
    match.results.some(Boolean) || match.winnerSeed !== null
  )) return 'Invalid tournament.';
  if (state.phase === 'playing') return validPlayingState(state, current);
  if (state.currentGame !== null) return 'Invalid tournament.';
  if (state.phase === 'ready')
    return state.activePlayer === 0 && !current.results.some(Boolean) && noCompletion(state)
      ? null : 'Invalid tournament.';
  if (state.phase === 'betweenTurns')
    return state.activePlayer === 1 && current.results[0] !== null && current.results[1] === null &&
      noCompletion(state) ? null : 'Invalid tournament.';
  if (state.phase === 'betweenMatches')
    return state.activePlayer === 0 && current.winnerSeed !== null &&
      state.currentMatchIndex < state.matches.length - 1 && noCompletion(state)
      ? null : 'Invalid tournament.';
  const final = state.matches[state.matches.length - 1];
  return state.phase === 'complete' && state.currentMatchIndex === state.matches.length - 1 &&
    state.activePlayer === 1 && final?.winnerSeed === state.championSeed &&
    state.championSeed !== null && isTimestamp(state.completedAt)
    ? null : 'Invalid tournament.';
}

function validPlayingState(state: TournamentState, current: TournamentMatch): string | null {
  const priorTurnDone = state.activePlayer === 0
    ? current.results[0] === null
    : current.results[0] !== null;
  const game = typeof state.currentGame === 'string' ? decodeSnapshot(state.currentGame) : null;
  return priorTurnDone && current.results[state.activePlayer] === null &&
    game?.boardCode === current.boardCode && game.matched.length < game.deck.length &&
    noCompletion(state) ? null : 'Invalid tournament.';
}

function noCompletion(state: TournamentState): boolean {
  return state.championSeed === null && state.completedAt === null;
}

function sameNext(first: TournamentMatch['next'], second: TournamentMatch['next']): boolean {
  return first?.matchIndex === second?.matchIndex && first?.playerSlot === second?.playerSlot;
}
import { useEffect, useRef } from 'react';
import type { RefObject } from 'react';
import { Board } from '../board/Board.tsx';
import type { BoardFocus } from '../board/Board.tsx';
import { isWon } from '../game.ts';
import { GameStatus } from '../status/GameStatus.tsx';
import { TournamentBracket } from './TournamentBracket.tsx';
import { tournamentPlayer } from './rules.ts';
import type { GameState } from '../game.ts';
import type { TournamentState } from './types.ts';

interface TournamentCurrentProps {
  readonly tournament: TournamentState;
  readonly game: GameState;
  readonly generation: number;
  readonly celebration: boolean;
  readonly startButton: RefObject<HTMLButtonElement | null>;
  activate(index: number): void;
  startTurn(): void;
  nextMatch(): void;
  back(): void;
}

export function TournamentCurrent({
  tournament,
  game,
  generation,
  celebration,
  startButton,
  activate,
  startTurn,
  nextMatch,
  back,
}: TournamentCurrentProps) {
  const board = useRef<BoardFocus>(null);
  const shouldFocusBoard = useRef(false);
  const currentMatch = tournament.matches[tournament.currentMatchIndex];
  const activeSeed = currentMatch?.players[tournament.activePlayer] ?? null;
  const activeName = tournamentPlayer(tournament, activeSeed)?.name;
  const champion = tournamentPlayer(tournament, tournament.championSeed)?.name;
  const showBoard = tournament.phase === 'playing' ||
    (isWon(game) && ['betweenTurns', 'betweenMatches', 'complete'].includes(tournament.phase));

  useEffect(() => {
    if (shouldFocusBoard.current && tournament.phase === 'playing') {
      board.current?.focusRemembered();
      shouldFocusBoard.current = false;
    }
  }, [generation, tournament.phase]);

  function beginTurn(): void {
    shouldFocusBoard.current = true;
    startTurn();
  }

  if (!currentMatch) return null;
  return (
    <section className="tournament-current" aria-labelledby="tournament-round-heading">
      <h3 id="tournament-round-heading">Round: {currentMatch.round}</h3>
      <p>Match {tournament.currentMatchIndex + 1} of {tournament.matches.length}</p>
      {tournament.phase !== 'betweenMatches' && tournament.phase !== 'complete' && activeName && (
        <p className="tournament-now-playing">Now playing: {activeName}</p>
      )}
      <p className="tournament-tie-rule">
        Fewer moves wins. Equal move counts go to the faster time, then the higher seed.
      </p>
      {tournament.phase === 'ready' && (
        <button ref={startButton} type="button" className="control" onClick={beginTurn}>
          Start turn
        </button>
      )}
      {tournament.phase === 'betweenTurns' && (
        <button ref={startButton} type="button" className="control" onClick={beginTurn}>
          Next turn
        </button>
      )}
      {tournament.phase === 'betweenMatches' && (
        <button ref={startButton} type="button" className="control" onClick={nextMatch}>
          Next match
        </button>
      )}
      {tournament.phase === 'playing' && <p>Finish the board to continue.</p>}
      {tournament.phase === 'complete' ? (
        <>
          <h3>Champion: {champion}</h3>
          <button type="button" className="control" onClick={back}>Back to game</button>
        </>
      ) : (
        <button type="button" className="control" onClick={back}>Leave tournament</button>
      )}
      {showBoard && (
        <>
          <GameStatus game={game} best={undefined} celebration={celebration} showBest={false} />
          <p id="tournament-board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space reveals a card.
          </p>
          <Board
            key={generation}
            game={game}
            activate={activate}
            ref={board}
            helpId="tournament-board-help"
          />
        </>
      )}
      <TournamentBracket tournament={tournament} highlightCurrent />
    </section>
  );
}

