    result.elapsedMs >= 0 &&
    result.elapsedMs <= ELAPSED_MAX_MS
  );
}

function replaceMatch(
  matches: readonly TournamentMatch[],
  index: number,
  match: TournamentMatch,
): TournamentMatch[] {
  return matches.map((entry, position) => (position === index ? match : entry));
}
export function normalizePlayerName(draft: string): string {
  return draft.trim().replace(/\s+/gu, ' ').normalize('NFC');
}

export function hasValidPlayerNames(names: readonly string[]): boolean {
  return names.every((name) => {
    const length = Array.from(name).length;
    return length >= 2 && length <= 20 && normalizePlayerName(name) === name;
  });
}

export function hasUniquePlayerNames(names: readonly string[]): boolean {
  const seen = new Set<string>();
  for (const name of names) {
    const comparison = name.toLowerCase();
    if (seen.has(comparison)) return false;
    seen.add(comparison);
  }
  return true;
}
import { hasExactKeys, isJsonObject, isWithinBytes, parseJson } from '../saved-format.ts';
import { validateTournamentState } from './validate-state.ts';
import type { TournamentState } from './types.ts';

const TOURNAMENT_FORMAT = 'neon-pairs/tournament';
const TOURNAMENT_VERSION = 1;
const TOURNAMENT_TEXT_MAX_BYTES = 65_536;

type TournamentDecode =
  | { readonly ok: true; readonly tournament: TournamentState }
  | { readonly ok: false; readonly message: string };

export function encodeTournament(tournament: TournamentState, currentGame: string | null): string {
  const data = { ...tournament, currentGame };
  const validation = validateTournamentState(data);
  if (!('state' in validation)) throw new Error('Cannot export an invalid tournament.');
  return JSON.stringify(
    sortKeys({ format: TOURNAMENT_FORMAT, tournament: data, version: TOURNAMENT_VERSION }),
    null,
    2,
  );
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (typeof value !== 'object' || value === null) return value;
  return Object.fromEntries(
    Object.entries(value).sort(([first], [second]) => first.localeCompare(second))
      .map(([key, entry]) => [key, sortKeys(entry)]),
  );
}

export function decodeTournament(text: string): TournamentDecode {
  if (text.length > TOURNAMENT_TEXT_MAX_BYTES || !isWithinBytes(text, TOURNAMENT_TEXT_MAX_BYTES))
    return { ok: false, message: 'Invalid tournament.' };
  const value = parseJson(text);
  try {
    const envelope = objectWithKeys(value, ['format', 'tournament', 'version']);
    if (!envelope) return { ok: false, message: 'Invalid tournament.' };
    if (envelope.format !== TOURNAMENT_FORMAT || envelope.version !== TOURNAMENT_VERSION)
      return { ok: false, message: 'Invalid tournament.' };
    const result = validateTournamentState(envelope.tournament);
    return 'state' in result
      ? { ok: true, tournament: result.state }
      : { ok: false, message: result.message };
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : 'Invalid tournament.' };
  }
}

function objectWithKeys(value: unknown, keys: readonly string[]): Record<string, unknown> | null {
  if (!isJsonObject(value)) return null;
  const record = value;
  const unknown = Object.keys(record).find((key) => !keys.includes(key));
  if (unknown) throw new Error(`Unknown field: ${unknown}.`);
  return hasExactKeys(record, keys) ? record : null;
}
import { isJsonObject, parseJson } from '../saved-format.ts';
import { validateTournamentState } from './validate-state.ts';
import type { TournamentState } from './types.ts';

const TOURNAMENTS_KEY = 'np3:tournaments';
const TOURNAMENT_RETENTION = 10;
export interface TournamentStore {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

export function readTournaments(store: TournamentStore | null): {
  readonly items: readonly TournamentState[];
  readonly available: boolean;
} {
  if (!store) return { items: [], available: false };
  try {
    const text = store.getItem(TOURNAMENTS_KEY);
    if (!text) return { items: [], available: true };
    const value = parseJson(text);
    if (!isJsonObject(value) || Object.keys(value).length !== 2 || value.v !== 3 || !Array.isArray(value.items))
      return { items: [], available: true };
    const items: TournamentState[] = [];
    for (const item of value.items) {
      const result = validateTournamentState(item);
      if (!('state' in result) || result.state.phase !== 'complete') return { items: [], available: true };
      items.push(result.state);
    }
    return { items: retainTournaments(items), available: true };
  } catch {
    return { items: [], available: false };
  }
}

export function writeTournaments(
  store: TournamentStore | null,
  items: readonly TournamentState[],
): { readonly success: boolean } {
  if (!store) return { success: false };
  try {
    store.setItem(TOURNAMENTS_KEY, JSON.stringify({ v: 3, items: retainTournaments(items) }));
    return { success: true };
  } catch {
    return { success: false };
  }
}

export function retainTournaments(items: readonly TournamentState[]): TournamentState[] {
  const unique = new Map(items.map((item) => [JSON.stringify(item), item]));
  return [...unique.values()]
    .sort((first, second) => (second.completedAt ?? '').localeCompare(first.completedAt ?? ''))
    .slice(0, TOURNAMENT_RETENTION);
}
import { useCallback, useRef, useState } from 'react';
import { readTournaments, retainTournaments, writeTournaments } from './storage.ts';
import type { TournamentStore } from './storage.ts';
import type { TournamentState } from './types.ts';

export function useTournamentHistory() {
  const [store] = useState(browserTournamentStore);
  const [initial] = useState(() => readTournaments(store));
  const [items, setItems] = useState(initial.items);
  const latest = useRef(items);
  const [available, setAvailable] = useState(initial.available);

  const add = useCallback((tournament: TournamentState): void => {
    const next = retainTournaments([tournament, ...latest.current]);
    latest.current = next;
    setItems(next);
    const saved = writeTournaments(store, next);
    setAvailable((wasAvailable) => wasAvailable && saved.success);
  }, [store]);

  return { items, available, add };
}

function browserTournamentStore(): TournamentStore | null {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}
import { useEffect, useRef, useState } from 'react';
import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { useGame } from '../session/use-game.ts';
import {
  advanceTournamentMatch,
  beginTournamentTurn,
  createTournament,
  finishTournamentTurn,
  roundPlan,
  stageSize,
  tournamentPlayer,
} from './rules.ts';
import type { TournamentPlayer, TournamentState } from './types.ts';

interface TournamentOptions {
  readonly announce: (text: string) => void;
  readonly onComplete: (tournament: TournamentState) => void;
}

export function useTournament({ announce, onComplete }: TournamentOptions) {
  const controller = useGame({ persistPreferences: false, recordBest: false, initialSize: 4 });
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const latest = useRef(tournament);
  const previousAnnouncement = useRef(controller.session.announcement);

  function commit(next: TournamentState): void {
    if (next === latest.current) return;
    latest.current = next;
    setTournament(next);
  }

  useEffect(() => {
    if (previousAnnouncement.current === controller.session.announcement) return;
    previousAnnouncement.current = controller.session.announcement;
    if (!isWon(controller.session.game) && controller.session.feedback)
      announce(controller.session.feedback);
  }, [announce, controller.session.announcement, controller.session.feedback, controller.session.game]);

  useEffect(() => {
    const current = latest.current;
    const game = controller.session.game;
    if (!current || current.phase !== 'playing' || !isWon(game)) return;
    const seed = current.matches[current.currentMatchIndex]?.players[current.activePlayer] ?? null;
    const player = tournamentPlayer(current, seed);
    const next = finishTournamentTurn(
      current,
      { moves: game.moves, elapsedMs: game.elapsedMs },
      new Date().toISOString(),
    );
    if (next === current) return;
    commit(next);
    if (next.phase === 'complete') {
      onComplete(next);
      announce(
        `${player?.name ?? 'Player'} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
          `Champion: ${tournamentPlayer(next, next.championSeed)?.name ?? ''}`,
      );
      return;
    }
    if (next.phase === 'betweenMatches') {
      const winner = tournamentPlayer(next, next.matches[next.currentMatchIndex]?.winnerSeed ?? null);
      announce(
        `${player?.name ?? 'Player'} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
          `${winner?.name ?? 'Player'} wins the ${current.matches[current.currentMatchIndex]?.round}.`,
      );
      return;
    }
    const nextPlayer = tournamentPlayer(next, next.matches[next.currentMatchIndex]?.players[1] ?? null);
    announce(
      `${player?.name ?? 'Player'} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
        `Now playing: ${nextPlayer?.name ?? ''}`,
    );
  }, [announce, controller.session.game, onComplete]);

  function start(players: readonly TournamentPlayer[]): void {
    const used = new Set<string>();
    const codes = roundPlan(players.length).map((round) => {
      let code = freshBoardCode(stageSize(round));
      while (used.has(code)) code = freshBoardCode(stageSize(round));
      used.add(code);
      return code;
    });
    const next = createTournament(players, codes, new Date().toISOString());
    if (!next) return;
    commit(next);
    announce(`Now playing: ${tournamentPlayer(next, next.matches[0]?.players[0] ?? null)?.name ?? ''}`);
  }

  function startTurn(): void {
    const current = latest.current;
    if (!current || (current.phase !== 'ready' && current.phase !== 'betweenTurns')) return;
    const match = current.matches[current.currentMatchIndex];
    const name = tournamentPlayer(current, match?.players[current.activePlayer] ?? null)?.name;
    if (!match || !name || !controller.loadBoard(match.boardCode)) return;
    commit(beginTournamentTurn(current));
    announce(`Now playing: ${name}`);
  }

  function nextMatch(): void {
    const current = latest.current;
    if (!current || current.phase !== 'betweenMatches') return;
    const next = advanceTournamentMatch(current);
    commit(next);
    const match = next.matches[next.currentMatchIndex];
    announce(`Now playing: ${tournamentPlayer(next, match?.players[0] ?? null)?.name ?? ''}`);
  }

  function load(imported: TournamentState): boolean {
    const currentGame = imported.currentGame;
    if (imported.phase === 'playing') {
      if (!currentGame || !controller.loadSnapshot(currentGame)) return false;
      controller.resume();
    } else {
      const match = imported.matches[imported.currentMatchIndex];
      if (!match || !controller.loadBoard(match.boardCode)) return false;
    }
    const restored = { ...imported, currentGame: null };
    commit(restored);
    if (restored.phase === 'complete') onComplete(restored);
    const match = restored.matches[restored.currentMatchIndex];
    const seed = restored.phase === 'betweenMatches'
      ? null
      : match?.players[restored.activePlayer] ?? null;
    announce(restored.phase === 'complete'
      ? `Champion: ${tournamentPlayer(restored, restored.championSeed)?.name ?? ''}`
      : seed === null
        ? 'Tournament loaded.'
        : `Now playing: ${tournamentPlayer(restored, seed)?.name ?? ''}`);
    return true;
  }

  return { controller, tournament, start, startTurn, nextMatch, load };
}

