import { activateCard, advanceGame, createGame, isWon } from '../game.ts';
import { SelectionKind } from '../selection.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { rememberBest } from './storage.ts';
import type { GameState } from '../game.ts';
import type { Preferences } from './storage.ts';

export interface Session {
  readonly game: GameState;
  readonly paused: boolean;
  readonly generation: number;
  readonly feedback: string;
  readonly loadNotice: string;
  readonly announcement: number;
  readonly celebration: boolean;
  readonly preferences: Preferences;
}

export const SessionNotice = {
  loaded: 'Loaded snapshot. Select Resume to continue.',
  loadedCompleted: 'Loaded completed snapshot.',
  invalidBoard: 'Invalid board code.',
  invalidSnapshot: 'Invalid snapshot.',
} as const;

export function initialSession(code: string, preferences: Preferences): Session {
  return {
    game: createGame(code),
    paused: false,
    generation: 0,
    feedback: '',
    loadNotice: '',
    announcement: 0,
    celebration: false,
    preferences,
  };
}

export function replaceGame(
  session: Session,
  game: GameState,
  imported: boolean,
  updatePreferenceSize = true,
): Session {
  const paused = imported && !isWon(game);
  const loadNotice = imported
    ? paused
      ? SessionNotice.loaded
      : SessionNotice.loadedCompleted
    : '';
  return {
    ...session,
    game,
    paused,
    generation: session.generation + 1,
    celebration: false,
    preferences: updatePreferenceSize
      ? { ...session.preferences, size: game.size }
      : session.preferences,
    // Only loads have a published status. A new deal clears the last turn result silently.
    announcement: imported ? session.announcement + 1 : session.announcement,
    feedback: loadNotice,
    loadNotice,
  };
}

export function tickSession(session: Session, generation: number, milliseconds: number): Session {
  if (session.generation !== generation || session.paused) return session;
  const game = advanceGame(session.game, milliseconds);
  return game === session.game ? session : { ...session, game };
}

export function activateSession(session: Session, index: number, recordBest = true): Session {
  if (session.paused) return session;
  const game = activateCard(session.game, index);
  if (game === session.game) return session;
  if (game.selection.kind === SelectionKind.one) return { ...session, game };
  const won = isWon(game);
  const feedback = won
    ? `Pair found. All pairs found in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}.`
    : game.selection.kind === SelectionKind.mismatch
      ? 'No match. Cards close after a short pause.'
      : `Pair found. ${game.matched.length / 2} ${game.matched.length === 2 ? 'pair' : 'pairs'} matched.`;
  const preferences = won && recordBest
    ? rememberBest(session.preferences, game.size, game.moves)
    : session.preferences;
  return {
    ...session,
    game,
    feedback,
    announcement: session.announcement + 1,
    preferences,
    celebration: won,
  };
}
import { useRef, useState } from 'react';
import { createGame } from '../game.ts';
import { parseBoardCode, isValidSize } from '../deck.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { freshBoardCode } from './fresh-board.ts';
import { activateSession, initialSession, replaceGame, SessionNotice } from './session.ts';
import { DEFAULT_SIZE, readPreferences } from './storage.ts';
import { browserStore, useSavedPreferences } from './use-saved-preferences.ts';
import { useSessionClock } from './use-session-clock.ts';
import type { Session } from './session.ts';

interface GameOptions {
  readonly active?: boolean;
  readonly persistPreferences?: boolean;
  readonly recordBest?: boolean;
  readonly initialSize?: number;
}

export function useGame(options: GameOptions = {}) {
  const active = options.active ?? true;
  const persistPreferences = options.persistPreferences ?? true;
  const recordBest = options.recordBest ?? true;
  const [store] = useState(() => (persistPreferences ? browserStore() : null));
  const [session, setSession] = useState(() => {
    const preferences = persistPreferences
      ? readPreferences(store)
      : { size: options.initialSize ?? DEFAULT_SIZE, bestMoves: {} };
    return initialSession(freshBoardCode(options.initialSize ?? preferences.size), preferences);
  });
  const current = useRef(session);

  function commit(next: Session): void {
    if (next === current.current) return;
    current.current = next;
    setSession(next);
  }

  const clock = useSessionClock(session, current, commit, active);
  useSavedPreferences(store, session.preferences, persistPreferences);

  function newGame(size = current.current.game.size): void {
    if (!isValidSize(size)) return;
    const next = createGame(freshBoardCode(size, current.current.game.seed));
    clock.reset();
    commit(replaceGame(current.current, next, false, persistPreferences));
  }

  function restart(): void {
    clock.reset();
    commit(
      replaceGame(current.current, createGame(current.current.game.boardCode), false, persistPreferences),
    );
  }

  function notice(feedback: string): void {
    commit({
      ...current.current,
      feedback,
      loadNotice: feedback,
      announcement: current.current.announcement + 1,
    });
  }

  function loadBoard(code: string): boolean {
    code = code.trim();
    if (!parseBoardCode(code)) {
      notice(SessionNotice.invalidBoard);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, createGame(code), false, persistPreferences));
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (!game) {
      notice(SessionNotice.invalidSnapshot);
      return false;
    }
    clock.reset();
    commit(replaceGame(current.current, game, true, persistPreferences));
    return true;
  }

  function exportSnapshot(): string {
    // Rendered state can trail the active clock by a tick.
    clock.synchronize();
    return encodeSnapshot(current.current.game);
  }

  function activate(index: number): void {
    clock.synchronize();
    commit(activateSession(current.current, index, recordBest));
  }

  function resume(): void {
    clock.reset();
    commit({
      ...current.current,
      paused: false,
      feedback: '',
      loadNotice: '',
    });
  }

  return { session, newGame, restart, loadBoard, loadSnapshot, exportSnapshot, activate, resume };
}
# Module layout policy

This page explains how Neon Pairs places behavior in the source tree and how to extend that structure without obscuring the game rules.

The current tree is small enough to read directly. It has no application framework around the game, no route hierarchy and no general service container. `src/main.tsx` mounts `Game`; the application then divides into rule functions, a session adapter and components for the board, controls and status. Source layout is the file inventory. This page explains the choices behind it.

## Follow behavior before file type

The board directory contains `Board.tsx`, `Card.tsx`, `Face.tsx`, navigation helpers, card descriptions, face design, styles and focused tests. Its contents answer a coherent set of questions: how a position is presented, how focus moves and how a face becomes visible. A separate top-level directory for every hook, type or stylesheet would make those questions harder to answer.

The session directory has a different responsibility. It connects rules to React state, browser observations and saved preferences. A feature lives in src/game/FEATURE/, and its rules live in src/game/FEATURE/rules.ts, which imports neither React nor any browser global. That placement gives a reader a predictable starting point for a feature's decisions, with the integration code close enough to inspect alongside them.

This convention applies to feature work; existing behaviors also use other filenames. The current core is in `game.ts`, `deck.ts`, `selection.ts`, `snapshot.ts`, `snapshot-selection.ts`, `saved-format.ts`, `elapsed-time.ts` and `replay.ts` directly under `src/game`. The board already uses focused names such as `keyboard.ts` and `card-state.ts`.

