import { useRef } from 'react';
import { Board } from './board/Board.tsx';
import { Controls } from './controls/Controls.tsx';
import { Reproduction } from './controls/Reproduction.tsx';
import { GameResult } from './GameResult.tsx';
import { GameStatus } from './status/GameStatus.tsx';
import { useGame } from './session/use-game.ts';
import type { BoardFocus } from './board/Board.tsx';
import type { RefObject } from 'react';

interface SoloGameProps {
  readonly active: boolean;
  readonly tournamentButtonRef: RefObject<HTMLButtonElement | null>;
  openTournament(): void;
}

export function SoloGame({ active, tournamentButtonRef, openTournament }: SoloGameProps) {
  const controller = useGame({ active });
  const { session } = controller;
  const { game } = session;
  const board = useRef<BoardFocus>(null);

  function resume(): void {
    board.current?.focusRemembered();
    controller.resume();
  }

  return (
    <div hidden={!active}>
      <p className="intro">Reveal two cards. Match their shape and marker to keep the pair.</p>
      <Controls
        size={game.size}
        newGame={controller.newGame}
        restart={controller.restart}
        openTournament={openTournament}
        tournamentButtonRef={tournamentButtonRef}
      />
      <GameStatus
        game={game}
        best={session.preferences.bestMoves[String(game.size)]}
        celebration={session.celebration}
      />
      <p id="board-help" className="help">
        Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
        reveals a card.
      </p>
      <GameResult text={session.feedback} sequence={session.announcement} />
      <Board key={session.generation} game={game} activate={controller.activate} ref={board} />
      <Reproduction
        game={game}
        generation={session.generation}
        exportSnapshot={controller.exportSnapshot}
        loadBoard={controller.loadBoard}
        loadSnapshot={controller.loadSnapshot}
        notice={session.loadNotice}
        paused={session.paused}
        resume={resume}
      />
    </div>
  );
}
import { useCallback, useEffect, useRef, useState } from 'react';
import { decodeTournament, encodeTournament } from './format.ts';
import { hasUniquePlayerNames, hasValidPlayerNames, normalizePlayerName } from './names.ts';
import { GameResult } from '../GameResult.tsx';
import { TournamentCurrent } from './TournamentCurrent.tsx';
import { TournamentEntry } from './TournamentEntry.tsx';
import { TournamentHistory } from './TournamentHistory.tsx';
import { TournamentJsonPanel } from './TournamentJsonPanel.tsx';
import { useTournamentHistory } from './use-history.ts';
import { useTournament } from './use-tournament.ts';
import type { TournamentPlayer, TournamentState } from './types.ts';
import './tournament.css';

interface TournamentScreenProps {
  readonly status: { readonly text: string; readonly sequence: number };
  onBack(): void;
  announce(text: string): void;
}

export function TournamentScreen({ status, onBack, announce }: TournamentScreenProps) {
  const history = useTournamentHistory();
  const onComplete = useCallback(
    (tournament: TournamentState) => history.add(tournament),
    [history.add],
  );
  const tournamentController = useTournament({ announce, onComplete });
  const { tournament, controller } = tournamentController;
  const [playerCount, setPlayerCount] = useState(4);
  const [names, setNames] = useState(() => Array.from({ length: 8 }, () => ''));
  const [entryNotice, setEntryNotice] = useState('');
  const [focusStart, setFocusStart] = useState(false);
  const heading = useRef<HTMLHeadingElement>(null);
  const startButton = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    heading.current?.focus();
    announce('Tournament setup.');
  }, [announce]);
  useEffect(() => {
    if (!focusStart || !tournament) return;
    startButton.current?.focus();
    setFocusStart(false);
  }, [focusStart, tournament]);

  function changeName(index: number, value: string): void {
    setNames((current) => current.map((name, position) => (position === index ? value : name)));
  }

  function startTournament(): void {
    const acceptedNames = names.slice(0, playerCount).map(normalizePlayerName);
    if (!hasValidPlayerNames(acceptedNames)) {
      setEntryNotice('Use 2 to 20 characters.');
      announce('Use 2 to 20 characters.');
      return;
    }
    if (!hasUniquePlayerNames(acceptedNames)) {
      setEntryNotice('Each name must be different.');
      announce('Each name must be different.');
      return;
    }
    const players: TournamentPlayer[] = acceptedNames.map((name, index) => ({
      name,
      seed: index + 1,
    }));
    setEntryNotice('');
    tournamentController.start(players);
    setFocusStart(true);
  }

  const exportText = useCallback((): string | null => {
    const source = tournament ?? history.items[0];
    if (!source) return null;
    const snapshot = tournament?.phase === 'playing' ? controller.exportSnapshot() : null;
    return encodeTournament(source, snapshot);
  }, [controller, history.items, tournament]);

  const loadText = useCallback(
    (text: string) => {
      const decoded = decodeTournament(text);
      if (!decoded.ok) return { ok: false, message: decoded.message };
      if (!tournamentController.load(decoded.tournament))
        return { ok: false, message: 'Invalid tournament.' };
      return { ok: true, message: 'Tournament loaded.' };
    },
    [tournamentController],
  );

  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 id="tournament-heading" ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      <GameResult
        {...status}
        {...(status.text.startsWith('Now playing:') ? { className: 'tournament-now-playing' } : {})}
      />
      {!tournament && (
        <>
          <p className="tournament-intro">Enter 4 or 8 players to set up a knockout bracket.</p>
          <TournamentEntry
            playerCount={playerCount}
            names={names}
            notice={entryNotice}
            onPlayerCountChange={setPlayerCount}
            onNameChange={changeName}
            onStart={startTournament}
          />
          <button type="button" className="control tournament-exit" onClick={onBack}>
            Back to game
          </button>
        </>
      )}
      {tournament && (
        <TournamentCurrent
          tournament={tournament}
          game={controller.session.game}
          generation={controller.session.generation}
          celebration={controller.session.celebration}
          startButton={startButton}
          activate={controller.activate}
          startTurn={tournamentController.startTurn}
          nextMatch={tournamentController.nextMatch}
          back={onBack}
        />
      )}
      <TournamentJsonPanel exportText={exportText} loadText={loadText} announce={announce} />
      <TournamentHistory items={history.items} available={history.available} />
    </section>
  );
}
import { useEffect, useRef, useState } from 'react';
import { isWon } from '../game.ts';
import { formatElapsed } from '../elapsed-time.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { useGame } from '../session/use-game.ts';
import {
  advanceTournamentMatch,
  beginTournamentTurn,
  createTournament,
  roundPlan,
  stageSize,
} from './rules.ts';
import { finishTournamentTurn, tournamentPlayer } from './results.ts';
import type { TournamentPlayer, TournamentState } from './types.ts';

interface TournamentOptions {
  readonly announce: (text: string) => void;
  readonly onComplete: (tournament: TournamentState) => void;
}

export function useTournament({ announce, onComplete }: TournamentOptions) {
  const controller = useGame({ persistPreferences: false, recordBest: false, initialSize: 4 });
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const latest = useRef(tournament);
  const previousAnnouncement = useRef(controller.session.announcement);

  function commit(next: TournamentState): void {
    if (next === latest.current) return;
    latest.current = next;
    setTournament(next);
  }

  useEffect(() => {
    if (previousAnnouncement.current === controller.session.announcement) return;
    previousAnnouncement.current = controller.session.announcement;
    if (!isWon(controller.session.game) && controller.session.feedback)
      announce(controller.session.feedback);
  }, [
    announce,
    controller.session.announcement,
    controller.session.feedback,
    controller.session.game,
  ]);

  useEffect(() => {
    const current = latest.current;
    const game = controller.session.game;
    if (!current || current.phase !== 'playing' || !isWon(game)) return;
    const seed = current.matches[current.currentMatchIndex]?.players[current.activePlayer] ?? null;
    const player = tournamentPlayer(current, seed);
    const next = finishTournamentTurn(
      current,
      { moves: game.moves, elapsedMs: game.elapsedMs },
      new Date().toISOString(),
    );
    if (next === current) return;
    commit(next);
    if (next.phase === 'complete') {
      onComplete(next);
      announce(
        `${player?.name ?? 'Player'} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
          `Champion: ${tournamentPlayer(next, next.championSeed)?.name ?? ''}`,
      );
      return;
    }
    if (next.phase === 'betweenMatches') {
      const winner = tournamentPlayer(
        next,
        next.matches[next.currentMatchIndex]?.winnerSeed ?? null,
      );
      announce(
        `${player?.name ?? 'Player'} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
          `${winner?.name ?? 'Player'} wins the ${current.matches[current.currentMatchIndex]?.round}.`,
      );
      return;
    }
    const nextPlayer = tournamentPlayer(
      next,
      next.matches[next.currentMatchIndex]?.players[1] ?? null,
    );
    announce(
      `${player?.name ?? 'Player'} finished in ${game.moves} moves and ${formatElapsed(game.elapsedMs)}. ` +
        `Now playing: ${nextPlayer?.name ?? ''}`,
    );
  }, [announce, controller.session.game, onComplete]);

  function start(players: readonly TournamentPlayer[]): void {
    const used = new Set<string>();
    const codes = roundPlan(players.length).map((round) => {
      let code = freshBoardCode(stageSize(round));
      while (used.has(code)) code = freshBoardCode(stageSize(round));
      used.add(code);
      return code;
    });
    const next = createTournament(players, codes, new Date().toISOString());
    if (!next) return;
    commit(next);
    announce(
      `Now playing: ${tournamentPlayer(next, next.matches[0]?.players[0] ?? null)?.name ?? ''}`,
    );
  }

  function startTurn(): void {
    const current = latest.current;
    if (!current || (current.phase !== 'ready' && current.phase !== 'betweenTurns')) return;
    const match = current.matches[current.currentMatchIndex];
    const name = tournamentPlayer(current, match?.players[current.activePlayer] ?? null)?.name;
    if (!match || !name || !controller.loadBoard(match.boardCode)) return;
    commit(beginTournamentTurn(current));
    announce(`Now playing: ${name}`);
  }

  function nextMatch(): void {
    const current = latest.current;
    if (!current || current.phase !== 'betweenMatches') return;
    const next = advanceTournamentMatch(current);
    commit(next);
    const match = next.matches[next.currentMatchIndex];
    announce(`Now playing: ${tournamentPlayer(next, match?.players[0] ?? null)?.name ?? ''}`);
  }

  function load(imported: TournamentState): boolean {
    const currentGame = imported.currentGame;
    if (imported.phase === 'playing') {
      if (!currentGame || !controller.loadSnapshot(currentGame)) return false;
      controller.resume();
    } else {
      const match = imported.matches[imported.currentMatchIndex];
      if (!match || !controller.loadBoard(match.boardCode)) return false;
    }
    const restored = { ...imported, currentGame: null };
    commit(restored);
    if (restored.phase === 'complete') onComplete(restored);
    const match = restored.matches[restored.currentMatchIndex];
    const seed =
      restored.phase === 'betweenMatches' ? null : (match?.players[restored.activePlayer] ?? null);
    announce(
      restored.phase === 'complete'
        ? `Champion: ${tournamentPlayer(restored, restored.championSeed)?.name ?? ''}`
        : seed === null
          ? 'Tournament loaded.'
          : `Now playing: ${tournamentPlayer(restored, seed)?.name ?? ''}`,
    );
    return true;
  }

  return { controller, tournament, start, startTurn, nextMatch, load };
}

